export interface Question {
  q: string;
  choices: string[];
  answer: number; // index into choices
  explain: string;
  // Name of the Pattern (from data/curriculum.ts) within this subskill that
  // this question tests, when it maps cleanly to exactly one pattern's
  // method. Used to show a method-based explanation tied back to the
  // lesson when a student answers incorrectly. Omitted for questions that
  // don't cleanly map to a single current pattern.
  pattern?: string;
  // Shown as a pill on the practice quiz, same styling as worked examples.
  // Assigned by a length/complexity heuristic across the whole bank rather
  // than hand-graded per question -- a fast first pass, not a guarantee
  // every label is exactly right.
  difficulty?: "easy" | "medium" | "hard";
  // The exact substring of `q` (as it literally appears there) to render
  // underlined -- the tested word for a Words in Context question, or the
  // specific sentence a text-structure "underlined sentence" question is
  // asking about. Matches the real exam's own underline convention instead
  // of leaving the student to relocate it themselves.
  underline?: string;
}

